const s = $('Gym Settings').first().json;
const NL = String.fromCharCode(10);
const DAY = 86400000;
const now = Date.now();
const members = $('Get All Members').all().map(i => i.json).filter(m => m.member_ref);
const outreach = $('Get Outreach Log').all().map(i => i.json).filter(o => o.member_ref && o.sent_at);
const visitsByRef = {};
let visitsThisWeek = 0;
let visitsLastWeek = 0;
for (const item of $input.all()) {
  const v = item.json;
  if (!v.member_ref || !v.checked_in_at) continue;
  const t = new Date(v.checked_in_at).getTime();
  if (isNaN(t) || t > now) continue;
  if (now - t <= 7 * DAY) visitsThisWeek += 1;
  else if (now - t <= 14 * DAY) visitsLastWeek += 1;
  if (!visitsByRef[v.member_ref]) visitsByRef[v.member_ref] = [];
  visitsByRef[v.member_ref].push(t);
}
for (const k of Object.keys(visitsByRef)) visitsByRef[k].sort((a, b) => a - b);
const memberByRef = {};
for (const m of members) memberByRef[m.member_ref] = m;
const active = members.filter(m => String(m.status || 'active').toLowerCase() === 'active');
const high = active.filter(m => m.risk_level === 'high').sort((a, b) => Number(b.monthly_fee || 0) - Number(a.monthly_fee || 0) || Number(b.risk_score || 0) - Number(a.risk_score || 0));
const medium = active.filter(m => m.risk_level === 'medium');
const fee = ref => Number((memberByRef[ref] && memberByRef[ref].monthly_fee) || 0);
const revenueAtRisk = high.concat(medium).reduce((a, m) => a + Number(m.monthly_fee || 0), 0);
const latestByRef = {};
for (const o of outreach) {
  const t = new Date(o.sent_at).getTime();
  if (isNaN(t)) continue;
  if (!latestByRef[o.member_ref] || latestByRef[o.member_ref].t < t) latestByRef[o.member_ref] = { t, o };
}
const wins = [];
let decided = 0;
for (const ref of Object.keys(latestByRef)) {
  const sent = latestByRef[ref].t;
  const back = (visitsByRef[ref] || []).find(t => t > sent && t <= sent + 14 * DAY);
  if (back) {
    decided += 1;
    const m = memberByRef[ref] || {};
    wins.push({ ref, name: m.name || latestByRef[ref].o.name, fee: fee(ref), sentAt: sent, backAt: back, daysToReturn: Math.max(0, Math.round((back - sent) / DAY)) });
  } else if (now - sent >= 14 * DAY) {
    decided += 1;
  }
}
wins.sort((a, b) => b.backAt - a.backAt);
const winsThisWeek = wins.filter(w => now - w.backAt <= 7 * DAY);
const wins30 = wins.filter(w => now - w.backAt <= 30 * DAY);
const revenueWonBack30 = wins30.reduce((a, w) => a + w.fee, 0);
const sentThisWeek = outreach.filter(o => now - new Date(o.sent_at).getTime() <= 7 * DAY).length;
const winRate = decided ? Math.round((wins.length / decided) * 100) : null;
const stats = {
  gymName: s.gymName,
  weekEnding: new Date(now).toISOString().slice(0, 10),
  activeMembers: active.length,
  highRisk: high.length,
  mediumRisk: medium.length,
  monthlyRevenueAtRisk: revenueAtRisk,
  winbackEmailsThisWeek: sentThisWeek,
  membersBackThisWeek: winsThisWeek.length,
  membersBackLast30Days: wins30.length,
  monthlyRevenueWonBackLast30Days: revenueWonBack30,
  yearlyValueIfTheyStay: revenueWonBack30 * 12,
  winbackRatePercent: winRate,
  visitsThisWeek,
  visitsLastWeek
};
const topRisk = high.slice(0, 8).map(m => ({ name: m.name, plan: m.plan, trainer: m.trainer, fee: Number(m.monthly_fee || 0), score: m.risk_score, reasons: m.risk_reasons, contacted: !!m.last_outreach_at }));
const system = [
  'You are a retention analyst writing a short weekly note for the owner of a gym.',
  'Use only the numbers given. Never invent data. Be specific, calm and practical, no hype, no emojis.',
  'Return only JSON: {"headline": "one sentence under 14 words", "summary": "2 to 3 sentences, under 70 words", "actions": ["3 short, specific actions for this week, naming members or trainers where useful"]}'
].join(NL);
const user = [
  'Weekly numbers: ' + JSON.stringify(stats),
  'Members who came back after a win-back email (latest first): ' + JSON.stringify(wins30.slice(0, 10).map(w => ({ name: w.name, daysToReturn: w.daysToReturn, monthlyFee: w.fee }))),
  'Highest-value members at high risk right now: ' + JSON.stringify(topRisk)
].join(NL);
return [{ json: { stats, wins: wins30.slice(0, 12), topRisk, system_prompt: system, user_prompt: user } }];

const s = $('Gym Settings').first().json;
const data = $('Calculate Weekly ROI').first().json;
const st = data.stats;
const r = $input.first().json || {};
let text = '';
if (typeof r.merged_response === 'string') text = r.merged_response;
else if (Array.isArray(r.content)) text = r.content.filter(c => c && c.type === 'text').map(c => c.text).join('');
else if (typeof r.content === 'string') text = r.content;
else if (typeof r.text === 'string') text = r.text;
let ai = null;
try { ai = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)); } catch (e) {}
if (!ai || !ai.headline) {
  ai = {
    headline: st.membersBackLast30Days + ' members came back after a win-back email this month',
    summary: st.highRisk + ' members are at high risk right now, with ' + s.currency + st.monthlyRevenueAtRisk + ' of monthly revenue at stake.',
    actions: ['Call the top 3 high-risk members personally', 'Ask each trainer to message their at-risk clients', 'Check in with new members in their first 30 days']
  };
}
const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = n => s.currency + Math.round(Number(n || 0)).toLocaleString('en-US');
const trend = st.visitsLastWeek ? Math.round(((st.visitsThisWeek - st.visitsLastWeek) / st.visitsLastWeek) * 100) : null;
const card = (value, label, bg, color) => '<td style="background:' + bg + ';padding:16px;border-radius:10px;width:25%;vertical-align:top"><div style="font-size:26px;font-weight:700;color:' + color + '">' + value + '</div><div style="font-size:12px;color:#667085;margin-top:4px">' + label + '</div></td>';
const gap = '<td style="width:8px"></td>';
const winsHtml = data.wins.length
  ? data.wins.map(w => '<tr><td style="padding:8px;border-bottom:1px solid #eee">' + esc(w.name) + '</td><td style="padding:8px;border-bottom:1px solid #eee;color:#667085">back ' + w.daysToReturn + ' day(s) after the email</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right">' + money(w.fee) + '/mo</td></tr>').join('')
  : '<tr><td style="padding:8px;color:#667085">No returns yet. Win-backs usually show up within 14 days.</td></tr>';
const riskHtml = data.topRisk.length
  ? data.topRisk.map(m => '<tr><td style="padding:8px;border-bottom:1px solid #eee"><strong>' + esc(m.name) + '</strong><br><span style="font-size:12px;color:#667085">' + esc(m.plan) + ' · ' + esc(m.trainer) + (m.contacted ? ' · emailed' : '') + '</span></td><td style="padding:8px;border-bottom:1px solid #eee;font-size:13px">' + esc(m.reasons) + '</td><td style="padding:8px;border-bottom:1px solid #eee;text-align:right">' + money(m.fee) + '/mo</td></tr>').join('')
  : '<tr><td style="padding:8px;color:#667085">No high-risk members this week.</td></tr>';
const actionsHtml = (ai.actions || []).map(a => '<li style="margin-bottom:6px">' + esc(a) + '</li>').join('');
const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;color:#101828">' +
  '<p style="margin:0;color:#667085;font-size:13px">' + esc(s.gymName) + ' · Weekly retention report · ' + esc(st.weekEnding) + '</p>' +
  '<h1 style="font-size:22px;margin:6px 0 12px">' + esc(ai.headline) + '</h1>' +
  '<p style="font-size:15px;line-height:1.5;margin:0 0 18px">' + esc(ai.summary) + '</p>' +
  '<table style="width:100%;border-collapse:collapse;margin-bottom:22px"><tr>' +
  card(money(st.monthlyRevenueWonBackLast30Days), 'monthly revenue won back (30 days)', '#ecfdf3', '#067647') + gap +
  card(st.membersBackLast30Days, 'members back after a win-back email', '#ecfdf3', '#067647') + gap +
  card(money(st.monthlyRevenueAtRisk), 'monthly revenue at risk now', '#fef3f2', '#b42318') + gap +
  card(st.winbackRatePercent === null ? '-' : st.winbackRatePercent + '%', 'win-back rate', '#f2f4f7', '#101828') +
  '</tr></table>' +
  '<p style="font-size:14px;margin:0 0 18px">' + st.activeMembers + ' active members · ' + st.highRisk + ' high risk · ' + st.mediumRisk + ' medium risk · ' + st.winbackEmailsThisWeek + ' win-back emails sent this week · ' + st.visitsThisWeek + ' visits this week' + (trend === null ? '' : ' (' + (trend >= 0 ? '+' : '') + trend + '% vs last week)') + '</p>' +
  '<h3 style="margin:0 0 8px">This week, do this</h3><ol style="margin:0 0 20px;padding-left:20px;font-size:14px">' + actionsHtml + '</ol>' +
  '<h3 style="margin:0 0 8px">Came back after a win-back email</h3><table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px">' + winsHtml + '</table>' +
  '<h3 style="margin:0 0 8px">Highest-value members at risk</h3><table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px">' + riskHtml + '</table>' +
  '<p style="font-size:12px;color:#98a2b3">"Won back" counts members who visited within 14 days of a win-back email. Yearly value if they stay: ' + money(st.yearlyValueIfTheyStay) + '. Sent by Gym Churn Radar' + (s.demoMode ? ' (demo mode)' : '') + '.</p>' +
  '</div>';
const subject = 'Weekly retention: ' + money(st.monthlyRevenueWonBackLast30Days) + '/mo won back · ' + st.highRisk + ' members at risk';
return [{ json: { subject, html } }];
